vrml.10:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Shape : 4
COMPONENT Lighting : 3
COMPONENT CubeMapTexturing : 3
COMPONENT Texturing : 3
COMPONENT Layering : 1
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1
COMPONENT X_ITE : 1

Viewpoint {
  position 0 0 6
}

Background {
  skyColor 0.15 0.15 0.18
}

EnvironmentLight {
  specularTexture ImageCubeMapTexture {
    url "../synthetic-rea-b02/pbr/env.png"
  }
}

DirectionalLight {
  color 1 0.95 0.9
  intensity 0.8
  direction -0.4 -0.6 -0.7
}

PointLight {
  color 0.6 0.8 1
  intensity 2
  attenuation 0 0 1
  location 2.5 2 3
  radius 20
}

Transform {
  translation 0 0 -3
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 1 1
      }
      texture ImageTexture {
        url "../synthetic-rea-b03/proj-checker.png"
      }
    }
    geometry Box {
      size 8 6 0.1
    }
  }
}

Transform {
  translation -1.5 0.8 -1.5
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 0.2 0.2
      }
    }
    geometry Box {
      size 0.6 2.5 0.3
    }
  }
}

Transform {
  translation 1.5 -0.8 -1.5
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.2 0.4 1
        transparency 0.5
      }
    }
    geometry Cone {
      height 1.5
      bottomRadius 0.5
    }
  }
}

DEF D1 DispersionMaterialExtension { }

DEF TR TransmissionMaterialExtension {
  transmission 1
}

DEF VO VolumeMaterialExtension {
  thickness 0.8
}

DEF M1 PhysicalMaterial {
  metallic 0
  roughness 0
  extensions [
    USE TR
    USE VO
    USE D1
  ]
}

DEF M2 PhysicalMaterial {
  metallic 0
  roughness 0
  extensions [
    USE TR
    USE VO
  ]
}

DEF M3 PhysicalMaterial {
  metallic 0
  roughness 0
  extensions [
    USE TR
    USE VO
    DEF D3 DispersionMaterialExtension {
      dispersion 6
    }
  ]
}

DEF G1 Group {
  children DEF S1 Transform {
    translation -1.4 0.6 0
    children Shape {
      appearance Appearance {
        material USE M1
      }
      geometry Sphere {
        radius 0.6
      }
    }
  }
}

DEF S2 Transform {
  translation 0 0.6 0
  children Shape {
    appearance Appearance {
      material USE M2
    }
    geometry Sphere {
      radius 0.6
    }
  }
}

DEF S3 Transform {
  translation 1.4 0.6 0
  children Shape {
    appearance Appearance {
      material USE M3
    }
    geometry Sphere {
      radius 0.6
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log ""
  initializeOnly SFNode   d1 USE D1
  initializeOnly SFNode   d3 USE D3
  initializeOnly SFNode   m2 USE M2
  initializeOnly SFNode   m3 USE M3
  initializeOnly SFNode   tr USE TR
  initializeOnly SFNode   vo USE VO
  initializeOnly SFNode   g1 USE G1
  initializeOnly SFNode   s1 USE S1
  initializeOnly SFNode   s2 USE S2

  url "javascript:
var made = null;
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') d1 .dispersion = 10;
   if (k == 'b') d1 .dispersion = -4;
   if (k == 'c') d3 .dispersion = 30;
   if (k == 'd') { made = Browser .currentScene .createNode ('DispersionMaterialExtension'); made .dispersion = 12; m2 .extensions = new MFNode (tr, vo, made); }
   if (k == 'e') made .dispersion = 2;
   if (k == 'f') m3 .extensions = new MFNode (tr, vo);
   if (k == 'g') vo .thickness = 1.6;
   if (k == 'h') tr .transmission = 0.4;
   if (k == 'i') g1 .removeChildren = new MFNode (s1);
   if (k == 'j') g1 .addChildren = new MFNode (s1);
   if (k == 'k') m2 .extensions = new MFNode ();
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

